@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + StreetAddress : string
  + Description : string
  + PickupTime : time
}

class Vehicle {
  + StorageSpace : float
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class Route {
  + Date : date
}

class Article {
  + Description : string
  + Category : string
  + IsFood : boolean
}

class DistributionCenter {
  + Name : string
}

class H2SEmployee {
  + Name : string
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class FoodBank {
  + Name : string
}

class Delivery {
  + Date : date
}

Resident "1" -- "*" PickupRequest
Resident "1" -- "0..1" Client
PickupRequest "*" -- "1" Vehicle
PickupRequest "*" -- "1" VolunteerDriver
Vehicle "1" -- "*" Route
VolunteerDriver "1" -- "*" Route
Route "1" -- "*" PickupRequest
Route "1" -- "*" Delivery
Route "1" -- "1" Vehicle
Article "*" -- "1" PickupRequest
Article "*" -- "1" DistributionCenter
Article "*" -- "1" H2SEmployee
DistributionCenter "1" -- "*" H2SEmployee
Client "1" -- "*" Delivery
Delivery "*" -- "1" VolunteerDriver
Delivery "*" -- "1" Article
Article "*" -- "0..1" FoodBank

@enduml

